      "literal": "“A rotten tie.”",
      "meaning": "A persistent relationship that one cannot easily break off, often spoken of critically or with teasing self-mockery.",
      "context": "The joking paraphrase in the English fits the long acquaintance. The expression is stronger than simply “an old friend”; tone determines how affectionate it sounds.",
      "example": "彼とは昔からの腐れ縁だ。",
